
create index if not exists lessons_path_sort_idx
  on public.lessons(path_id, sort_order, id);

do $skillsprint_seed$
declare q record;
begin
  for q in
    select * from (values
      ('web-html-02','web',3,'HTML structure','Choose a semantic landmark','Use the element that best describes the main content area.','Which HTML element represents the dominant content of a document?','<main>','<section>','<div>','<aside>','a','The main element identifies the page’s dominant content. A page should normally have one visible main landmark.','Look for the element whose name describes the page’s primary content.'),
      ('web-html-03','web',4,'HTML accessibility','Describe an informative image','Alternative text gives meaning to images when they cannot be seen.','Which attribute provides text alternatives for an informative image?','title','alt','src','role','b','The alt attribute supplies a text alternative for an image.','It is a two-letter attribute beginning with a.'),
      ('web-css-01','web',5,'CSS selectors','Target one class','Class selectors begin with a period.','Which selector targets every element with class="card"?','#card','.card','card','*card','b','A period introduces a class selector in CSS.','A class selector starts with a dot.'),
      ('web-css-02','web',6,'CSS box model','Understand element width','The box model includes content, padding, border and margin.','Which box-sizing value includes padding and border inside the declared width?','content-box','inherit','border-box','margin-box','c','With border-box, the declared width includes content, padding and border.','Choose the value that makes width calculations easier.'),
      ('web-css-03','web',7,'CSS layout','Align items in a row','Flexbox is useful for one-dimensional layouts.','Which declaration turns an element into a flex container?','display: grid;','position: flex;','display: flex;','flex: display;','c','display:flex establishes a flex formatting context for its children.','The property is display and the value is flex.'),
      ('web-css-04','web',8,'Responsive design','Use a media query','Media queries apply styles when a condition matches the device or viewport.','Which rule applies styles when the viewport is 600 pixels wide or less?','@media (max-width: 600px) { ... }','@screen 600px { ... }','@responsive (600px) { ... }','@media (min-width: 600px) { ... }','a','max-width:600px matches viewport widths at or below 600 pixels.','Use max-width when the rule is meant for small screens.'),
      ('web-css-05','web',9,'CSS cascade','Understand specificity','More specific selectors usually take precedence when origin and importance are equal.','Which selector has the greatest specificity?','p','.note','#note','article p','c','An ID selector has greater specificity than a class, element or compound element selector.','Compare element, class and ID selector weight.'),
      ('web-html-04','web',10,'HTML forms','Connect a label to an input','A label improves form usability and accessibility.','How should a label be associated with an input whose id is "email"?','Give the label name="email"','Set label for="email"','Set input label="email"','Put the label after the form','b','The label for attribute must match the input id.','The label uses the for attribute.'),
      ('logic-02','programming',2,'JavaScript variables','Choose a reassignment-friendly declaration','Use let for bindings that need reassignment.','Which declaration allows the variable value to be reassigned?','const score = 10;','let score = 10;','static score = 10;','fixed score = 10;','b','let creates a block-scoped variable that can be reassigned.','Avoid const when the binding itself must change.'),
      ('logic-03','programming',3,'Conditionals','Evaluate a comparison','A comparison expression produces a Boolean value.','What is the result of 7 >= 7 in JavaScript?','false','undefined','true','null','c','The >= operator includes equality, so 7 is greater than or equal to 7.','The equals case is included.'),
      ('logic-04','programming',4,'Loops','Count a loop iteration','A for loop can repeat while its condition remains true. Example: for (let i = 0; i < 4; i++) { work(); }','How many times does this loop run?','3','4','5','Forever','b','The values of i are 0, 1, 2 and 3: four iterations.','Start at zero and stop before four.'),
      ('logic-05','programming',5,'Functions','Return a value','return sends a value back to the caller.','What does the return keyword do inside a function?','Repeats the function','Sends a value back and ends that function call','Prints text to the screen','Creates a global variable','b','return ends the current function execution and provides the specified value.','It gives the caller a result.'),
      ('logic-06','programming',6,'Arrays','Read an array index','JavaScript arrays use zero-based indexing.','What does items[0] access?','The first item','The second item','The last item','The array length','a','An array’s first element is at index zero.','Counting starts at zero.'),
      ('logic-07','programming',7,'Equality','Compare without type coercion','Strict equality checks value and type.','Which operator checks equality without converting operand types?','=','==','===','!=','c','=== performs strict equality without type coercion.','It uses three equals signs.'),
      ('logic-08','programming',8,'Objects','Access an object property','Properties can be accessed with dot notation.','Given const learner = {name: "Ama"}, how do you read the name?','learner->name','learner.name','learner(name)','name.learner','b','Dot notation reads a named property from an object.','Write the object name, a dot, then the property.'),
      ('logic-09','programming',9,'Errors','Handle a possible exception','try/catch handles exceptions from a block of code.','Which block handles an exception thrown inside a try block?','finally only','catch','switch','for','b','catch receives the thrown error when the try block fails.','It is paired with try.'),
      ('database-02','database',2,'SQL filtering','Filter rows with WHERE','WHERE limits the rows returned by a query.','Which clause filters students to those in the IT programme?','ORDER BY programme','WHERE programme = ''IT''','GROUP BY programme','HAVING programme','b','WHERE applies a row-level condition before grouping.','Use the clause designed to filter rows.'),
      ('database-03','database',3,'SQL sorting','Sort newest records first','ORDER BY sorts result rows.','Which query sorts records from newest to oldest using created_at?','ORDER BY created_at ASC','SORT created_at DESC','ORDER BY created_at DESC','GROUP BY created_at DESC','c','DESC sorts values in descending order, placing later timestamps first.','Use ORDER BY with DESC.'),
      ('database-04','database',4,'SQL aggregation','Count records','COUNT(*) counts rows in the result set.','Which expression counts all rows in a group?','SUM(*)','COUNT(*)','TOTAL(*)','AVG(*)','b','COUNT(*) returns the number of rows, including rows with null columns.','Use the aggregate that counts rows.'),
      ('database-05','database',5,'SQL joins','Match related tables','A join combines rows based on a related column.','Which join returns only rows with matching keys in both tables?','LEFT JOIN','FULL OUTER JOIN','INNER JOIN','CROSS JOIN','c','INNER JOIN returns rows where the join condition matches in both tables.','Choose the join that keeps matching pairs only.'),
      ('database-06','database',6,'Relational keys','Identify a primary key','A primary key uniquely identifies each row.','Which statement about a primary key is correct?','It can contain duplicate values','It uniquely identifies each row and cannot be NULL','It must always be a text column','It is used only for sorting','b','A primary key enforces uniqueness and non-null identity for each row.','It must identify one row unambiguously.'),
      ('database-07','database',7,'Relational keys','Understand a foreign key','A foreign key enforces a relationship to a referenced key.','What is the main purpose of a foreign key?','To encrypt a table','To link rows and enforce referential integrity','To sort records automatically','To replace every index','b','A foreign key ensures referenced values exist in the related parent table.','Think about maintaining valid relationships between tables.'),
      ('database-08','database',8,'Normalization','Reduce repeating groups','First normal form requires atomic values and no repeating groups.','Which design best follows first normal form?','One column stores "HTML, CSS, SQL" as a list','Each skill is stored in its own row in a related table','Every table has one column only','All values are stored in one JSON string','b','Atomic values and no repeating groups are central to 1NF.','Avoid storing a list of multiple values in one field.'),
      ('database-09','database',9,'Database indexes','Speed up lookups','Indexes can improve reads but add storage and write overhead.','What is a common purpose of an index on student_id?','Make queries filtering by student_id faster','Automatically encrypt student_id','Prevent all duplicate rows in every column','Replace the primary key','a','An index helps the database locate matching rows more efficiently.','Think about how a database finds matching values.'),
      ('security-02','security',2,'Phishing','Spot a suspicious message','Phishing attempts to trick people into revealing information or opening malicious links.','Which message is the strongest phishing warning sign?','A known lecturer sends a timetable from the university portal','An unexpected message demands your password through an unfamiliar link','A teammate shares a document in the approved workspace','A system notification appears inside the official app','b','Urgency plus an unfamiliar credential-collection link is a strong phishing indicator.','Be careful when a message pressures you to enter credentials.'),
      ('security-03','security',3,'Authentication','Add another factor','MFA requires additional proof beyond a password.','Which option is an example of multi-factor authentication?','Password plus a one-time authenticator code','Two different passwords','Username plus email address','A longer username','a','A password plus a code from a separate authenticator is two different factors.','One factor is something you know; the other can be something you have.'),
      ('security-04','security',4,'Encryption','Protect data in transit','TLS protects data exchanged between a client and server.','What does HTTPS primarily provide for browser-to-server traffic?','A guarantee that a website is honest','Encrypted transport and server authentication using TLS','A guarantee that downloads contain no malware','Automatic backups','b','HTTPS uses TLS to protect the connection and authenticate the server.','HTTPS is HTTP secured with TLS.'),
      ('security-05','security',5,'Password storage','Store passwords safely','Passwords should be stored as salted password hashes using a suitable password hashing algorithm.','How should an application store user passwords?','As plain text','Reversibly encrypted with a shared key','As salted hashes using a password-hashing algorithm','In a public profile table','c','Password-hashing algorithms are designed to make offline guessing expensive; unique salts prevent identical passwords from sharing identical hashes.','Do not store passwords in a form that can simply be read back.'),
      ('security-06','security',6,'Access control','Apply least privilege','Users and processes should receive only permissions required for their tasks.','What does the principle of least privilege recommend?','Give every user administrator rights','Grant only the minimum access needed to perform assigned work','Disable all authentication','Share one account among a team','b','Least privilege limits the impact of mistakes and compromised accounts.','Access should be no broader than necessary.'),
      ('security-07','security',7,'Updates','Reduce known vulnerabilities','Security updates often fix publicly known software weaknesses.','Why should operating systems and applications receive security updates?','To remove every possible threat','To patch known vulnerabilities and reduce exposure','To make passwords unnecessary','To disable access logs','b','Patching closes known weaknesses before attackers can exploit them.','Updates often include fixes for security defects.'),
      ('security-08','security',8,'Backups','Recover from data loss','Backups should be tested and protected from the same failures as production systems.','Which practice makes backups more reliable?','Keep one backup on the same laptop only','Never test restore procedures','Maintain separate protected copies and test restoration regularly','Use the same administrator password everywhere','c','Separate protected copies plus restore tests provide evidence that recovery works.','A backup is useful only if it can be restored.'),
      ('security-09','security',9,'Network safety','Use public Wi-Fi carefully','Public networks may be untrusted.','When using public Wi-Fi, which action is safest?','Disable device updates','Use HTTPS, avoid untrusted downloads and use a trusted VPN when appropriate','Share files with everyone on the network','Turn off the device firewall','b','Encrypted connections and cautious network use reduce exposure on untrusted Wi-Fi.','Treat public networks as untrusted.'),
      ('tools-01','tools',1,'Git basics','Start version control','Git tracks changes in a project repository.','Which command initializes a new Git repository in the current folder?','git start','git init','git create','git open','b','git init creates a new local repository in the current directory.','It is a short command ending in init.'),
      ('tools-02','tools',2,'Git workflow','Check changed files','git status reports the state of the working tree and staging area.','Which command shows modified, staged and untracked files?','git status','git push','git log --all','git branch --delete','a','git status summarizes changes and the current branch state.','Use the command that reports repository status.'),
      ('tools-03','tools',3,'Git staging','Stage a file','Staging prepares changes for the next commit.','Which command stages index.html for the next commit?','git commit index.html','git add index.html','git push index.html','git stage --commit index.html','b','git add places the specified file into the staging area.','The command begins with add.'),
      ('tools-04','tools',4,'Git commits','Save a snapshot','A commit records staged changes with a message.','Which command creates a commit with the message "Add profile page"?','git save "Add profile page"','git commit -m "Add profile page"','git push -m "Add profile page"','git add -m "Add profile page"','b','git commit -m records the staged snapshot and its description.','Use commit and the -m option.'),
      ('tools-05','tools',5,'Git remotes','Send commits to a remote','git push sends local commits to a remote repository.','Which command pushes the current branch named main to origin?','git pull origin main','git push origin main','git clone origin main','git fetch --delete main','b','git push origin main publishes the local main branch to origin.','Push sends your branch to the named remote.'),
      ('tools-06','tools',6,'Git branches','Create a branch','Branches let you work on changes separately.','Which command creates and switches to a branch named feature/profile?','git branch feature/profile','git checkout -b feature/profile','git merge feature/profile','git reset feature/profile','b','git checkout -b creates the branch and checks it out.','Use the option that both creates and switches.'),
      ('tools-07','tools',7,'Terminal navigation','Change directories','cd changes the current working directory.','Which command moves into a folder named projects?','ls projects','cd projects','mkdir projects','pwd projects','b','cd changes the shell’s current directory.','It stands for change directory.'),
      ('tools-08','tools',8,'Project documentation','Explain a repository','A README introduces a project and explains how to use it.','Which file commonly explains a project, setup steps and usage?','LICENSE','README.md','node_modules','.env','b','README.md is the conventional project overview and setup guide.','Look for the file usually shown on a repository homepage.')
    ) as bank(id,path_id,sort_order,category,title,body,question,opt_a,opt_b,opt_c,opt_d,answer,explanation,hint)
  loop
    insert into public.lessons(
      id,path_id,type,category,title,subtitle,body,content,reward_xp,sort_order,is_published
    ) values (
      q.id,q.path_id,'multiple_choice',q.category,q.title,'Quick review · Beginner',q.body,
      jsonb_build_object(
        'question',q.question,
        'options',jsonb_build_array(
          jsonb_build_object('id','a','label',q.opt_a),
          jsonb_build_object('id','b','label',q.opt_b),
          jsonb_build_object('id','c','label',q.opt_c),
          jsonb_build_object('id','d','label',q.opt_d)
        ),
        'explanation',q.explanation,'hint',q.hint,'difficulty','beginner','review_weight',1
      ),25,q.sort_order,true
    )
    on conflict (id) do update set
      path_id=excluded.path_id,type=excluded.type,category=excluded.category,
      title=excluded.title,subtitle=excluded.subtitle,body=excluded.body,
      content=excluded.content,reward_xp=excluded.reward_xp,
      sort_order=excluded.sort_order,is_published=excluded.is_published,updated_at=now();

    insert into public.lesson_answer_keys(lesson_id,correct_answer)
    values(q.id,to_jsonb(q.answer::text))
    on conflict (lesson_id) do update set correct_answer=excluded.correct_answer;
  end loop;
end
$skillsprint_seed$;

comment on index public.lessons_path_sort_idx is 'Supports ordered learning-path lesson loading in SkillSprint.';
;
